import{_ as d,C as a,o as r,c as n,E as e,a2 as h}from"./chunks/framework.BdWD-ld-.js";const u=JSON.parse('{"title":"工具名没变，代码却变了：旧批准究竟认什么","description":"","frontmatter":{"title":"工具名没变，代码却变了：旧批准究竟认什么","article_type":"comparative-study","edition":"research-center","research_question":"可复用审批的实际查找键，是否区分不同请求、目标与代码实现？","summary":"相同工具名不一定是相同实现，相同身份字符串也未必绑定代码内容。对两个开源实现的固定源码及限定实验进行比较，可以看清工具身份、批准有效期与暂停恢复分别约束什么，并据此检查旧批准应覆盖哪些变化。","sources":["AG2 固定源码与维护者测试","SIDJUA 固定源码","2026-11-14 内部隔离实验"],"date":"2026-11-14","column":"open-source-engineering","category":"daily","pageClass":"runtime-v6-article","item_id":"SIG-20261114-003","lifecycle":"Published","cover":"/assets/covers/daily-2026-11-14-sig-20261114-003-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/engineering/2026-11-14-sig-20261114-003.md","filePath":"zh/engineering/2026-11-14-sig-20261114-003.md","lastUpdated":1794991269000}'),l={name:"zh/engineering/2026-11-14-sig-20261114-003.md"};function p(o,t,c,k,g,b){const s=a("ArticleCover"),i=a("ArticleTableScroll");return r(),n("div",null,[e(s,{image:"/assets/covers/daily-2026-11-14-sig-20261114-003-cover.png",kicker:"研究成果",title:"工具名没变，代码却变了：旧批准究竟认什么",summary:"相同工具名不一定是相同实现，相同身份字符串也未必绑定代码内容。对两个开源实现的固定源码及限定实验进行比较，可以看清工具身份、批准有效期与暂停恢复分别约束什么，并据此检查旧批准应覆盖哪些变化。",version:"2026-11-14",languageHref:"/en/engineering/2026-11-14-sig-20261114-003",languageLabel:"English"}),e(i,{language:"zh"}),t[0]||(t[0]=h(`<h1 id="工具名没变-代码却变了-旧批准究竟认什么" tabindex="-1">工具名没变，代码却变了：旧批准究竟认什么 <a class="header-anchor" href="#工具名没变-代码却变了-旧批准究竟认什么" aria-label="Permalink to &quot;工具名没变，代码却变了：旧批准究竟认什么&quot;">​</a></h1><p>两个函数的代码不同，却得到相同的工具身份字符串：只要模块名、限定名与公开工具名都不变，本次隔离实验中的身份函数就区分不了它们。这不是越权事故，却提出一个具体问题： <strong>旧批准认的是名称、代码，还是这次操作？答案要到复用键里找。</strong> 本文用两种实现和有对照的实验，帮助读者检查哪些变化应让旧批准失效。</p><h2 id="先分清三个不同的问题" tabindex="-1">先分清三个不同的问题 <a class="header-anchor" href="#先分清三个不同的问题" aria-label="Permalink to &quot;先分清三个不同的问题&quot;">​</a></h2><p>人工回复是否答复了正确的问题、旧批准是否覆盖当前操作、暂停后是否接回正确的请求，属于三个不同问题。界面上只有一次“批准”，实现里却可能有三种关联方式。</p><p>本文比较 AG2（开源智能体应用框架）的工具审批中间件与 SIDJUA（智能体操作治理系统）的操作前审批查询。两者来自独立作者，各自代码是其实现的一手依据；它们没有相互复现或验证安全性。我们的实验也只触及身份函数和数据库查询。</p><table tabindex="0"><thead><tr><th>检查位置</th><th>它回答什么</th><th>不能据此推出什么</th></tr></thead><tbody><tr><td>人工回复关联</td><td>这个答复对应哪次询问？</td><td>旧批准是否允许另一组参数</td></tr><tr><td>批准复用查询</td><td>当前调用是否属于已批准的范围？</td><td>最终工具一定执行或一定安全</td></tr><tr><td>暂停恢复关联</td><td>要接回哪一个等待中的请求？</td><td>读取批准记录时也采用同样的请求边界</td></tr></tbody></table><p>这张表是本文的研究解释，不是任何项目的统一接口约定。对应到代码，前者可通过回复的父消息编号关联，后者可通过暂停记录里的请求编号关联；中间那一层仍须单独查验。</p><h2 id="同名工具可以区分-代码内容却未必绑定" tabindex="-1">同名工具可以区分，代码内容却未必绑定 <a class="header-anchor" href="#同名工具可以区分-代码内容却未必绑定" aria-label="Permalink to &quot;同名工具可以区分，代码内容却未必绑定&quot;">​</a></h2><p>在固定版本的 <a href="https://raw.githubusercontent.com/ag2ai/ag2/10809bf298ff7c5c5a5c830651070c6f6634f90f/ag2/middleware/builtin/tools/approval.py" target="_blank" rel="noreferrer">AG2 审批中间件</a>里，授权键优先使用调用事件的来源标识，没有来源时退回工具名。用户选择“始终允许”后，该键写入会话变量；后续命中时直接调用执行链，不再询问。提示中可以展示参数，但参数没有进入这个复用键。</p><p><a href="https://raw.githubusercontent.com/ag2ai/ag2/10809bf298ff7c5c5a5c830651070c6f6634f90f/ag2/tools/final/function_tool.py" target="_blank" rel="noreferrer">工具身份函数</a>使用模块名、函数限定名与公开工具名拼出字符串。注册工具时，执行入口把这一来源标识写入事件副本后交给中间件。它能区分公开名称相同、限定名不同的函数，但这个身份不是代码内容的摘要。</p><p>我们在同日研究分析阶段已执行的内部实验中，提取原始语法树中的实际身份函数，仅移除属性装饰器，用合成函数和所有者调用。实验结果保存在<a href="/joinwell52/assets/evidence/2026-11-14-sig-20261114-003/identity-results.json">身份函数记录</a>。本文复用该记录，没有重新执行实验。</p><table tabindex="0"><thead><tr><th>只改变什么</th><th>身份字符串是否相等</th><th>本次观察的意义</th></tr></thead><tbody><tr><td>公开工具名相同，函数限定名不同</td><td>不相等</td><td>可区分这两个函数标识</td></tr><tr><td>函数体不同，模块名、限定名与公开名均保留</td><td>相等</td><td>不绑定函数体内容</td></tr><tr><td>函数相同，公开工具名换别名</td><td>不相等</td><td>公开名也是身份的一部分</td></tr></tbody></table><p><a href="https://raw.githubusercontent.com/ag2ai/ag2/10809bf298ff7c5c5a5c830651070c6f6634f90f/test/middleware/builtins/test_approval.py" target="_blank" rel="noreferrer">维护者测试</a>还写有同名不同函数、后续轮次复用，以及会话变量经序列化后重建工具仍复用批准的断言。这些测试是读到的作者测试，本文没有运行。它们与三个隔离用例的结论并不冲突：限定名隔离成立，不等于任意代码替换都会使旧批准失效。</p><p>时间也要分账。<a href="https://raw.githubusercontent.com/ag2ai/ag2/10809bf298ff7c5c5a5c830651070c6f6634f90f/ag2/context.py" target="_blank" rel="noreferrer">人工输入上下文</a>按回复的父编号等待答复，并把发送问题和等待一起纳入超时；超时会以人工输入错误结束。这约束的是等待多久，不是“始终允许”能保留多久。该审批中间件没有实现批准有效期、撤销或参数绑定；关闭“始终允许”会忽略既有复用标记，但不能把这一开关描述成完整撤销协议。</p><h2 id="请求编号被保存-不等于查询使用它" tabindex="-1">请求编号被保存，不等于查询使用它 <a class="header-anchor" href="#请求编号被保存-不等于查询使用它" aria-label="Permalink to &quot;请求编号被保存，不等于查询使用它&quot;">​</a></h2><p><a href="https://raw.githubusercontent.com/GoetzKohlberg/sidjua/747b5bb125c8cc94e7cb99a581dc63bedb2c9bb2/src/pipeline/approval.ts" target="_blank" rel="noreferrer">SIDJUA 审批源码</a>创建审批请求时，把请求编号写入元数据。查找函数的注释也写到请求编号匹配与兼容回退，但可执行查询没有使用这个编号。下面是保留筛选与排序含义的节选，省略了返回列；这是源码的结构化排版，不是建议接口。</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> approval_queue</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> agent_id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ?</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  AND</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> rule_triggered </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ?</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  AND</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> status</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> IN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;pending&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;approved&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;denied&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  AND</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> created_at </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> datetime</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;now&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, ? </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">||</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39; hours&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ORDER BY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> created_at </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DESC</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LIMIT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span></code></pre></div><p>传入查询的是代理编号、工作流动作模式与时间窗口。目标和请求编号不在该查询的比较条件里。这里的时间窗口按记录创建时间计算，不能写成批准决定之后重新计时。</p><p>内部实验在 SQLite（嵌入式关系数据库）中执行固定源码提取的实际查询，使用明确标注的合成请求和审批行。查询片段、逐项结果及重跑说明见<a href="/joinwell52/assets/evidence/2026-11-14-sig-20261114-003/evidence-guide.json">审批证据说明</a>和<a href="/joinwell52/assets/evidence/2026-11-14-sig-20261114-003/approval-results.json">查询结果记录</a>。不是把完整项目启动后试图执行操作。</p><table tabindex="0"><thead><tr><th>对照</th><th>取回的记录或结果</th></tr></thead><tbody><tr><td>原请求甲</td><td>甲的已批准行</td></tr><tr><td>换成请求乙并更换目标，其余不变</td><td>仍是甲的已批准行</td></tr><tr><td>仅更换代理</td><td>无记录</td></tr><tr><td>仅更换工作流动作模式</td><td>无记录</td></tr><tr><td>把原行移至有效窗口之外</td><td>无记录</td></tr><tr><td>待审批行，换请求</td><td>仍取回原待审批行</td></tr><tr><td>已拒绝行，换请求</td><td>仍取回原已拒绝行</td></tr><tr><td>原行改为查询不接受的已取消状态</td><td>无记录</td></tr><tr><td>再加入更新的合格拒绝行</td><td>选中新行，而非旧批准行</td></tr></tbody></table><p>八项单记录对照加一项最新记录对照，共九项。更换请求和目标是实验输入元数据的变化，查询本身没有接收这两个比较参数；不能把结果说成完整请求校验器接受了乙。时间用例刻意远离边界，也没有测试精确到期瞬间。</p><p><a href="https://raw.githubusercontent.com/GoetzKohlberg/sidjua/747b5bb125c8cc94e7cb99a581dc63bedb2c9bb2/src/pipeline/index.ts" target="_blank" rel="noreferrer">操作前管线</a>进一步显示：审批阶段的暂停或阻断会提前结束管线；构造暂停结果时，另一条查找待审批编号的查询，确实使用元数据里的请求编号。这正是关键区别： <strong>恢复记录可以按请求关联，批准复用却仍按更宽的条件查询。</strong> 审批阶段通过后还要继续预算、分类与策略等检查，所以命中一行已批准记录也不是最终操作获准的充分条件。</p><h2 id="把复用范围写成一组可反驳的条件" tabindex="-1">把复用范围写成一组可反驳的条件 <a class="header-anchor" href="#把复用范围写成一组可反驳的条件" aria-label="Permalink to &quot;把复用范围写成一组可反驳的条件&quot;">​</a></h2><p>我们的解释是：批准复用实际上划定了一组“被视为同类”的调用。AG2 主要按工具身份字符串与会话状态划类；SIDJUA 这条查询按代理、规则与创建时间窗口划类。窄或宽不应由名字听起来多精确来决定，而应由审批者明确同意的范围来决定。</p><p>一个反例是低风险、同一工作流内的重复操作：操作者可能本来就希望一次批准覆盖多个请求。此时跨请求复用可以是有意设计，逐次重新询问反而增加负担。本文不把较宽范围直接判为漏洞。真正需要解决的是：产品承诺、代码条件和测试预期是否一致；如果约定只批准目标甲，查询却根本不比较目标，契约就需要收窄或明确告知。</p><p>以“请求甲、目标甲已获批”为贯穿例子，评审者可按以下责任链取证。这是建议的核验方法，不是两个项目已经统一实现的流程。</p><table tabindex="0"><thead><tr><th>阶段</th><th>输入与责任主体</th><th>应取得的输出</th><th>应停止或另行审批的条件</th></tr></thead><tbody><tr><td>构造操作</td><td>调用方提交目标、参数与当前状态；可信入口核验身份</td><td>可归属的操作请求</td><td>身份或前置状态无法确认</td></tr><tr><td>展示批准</td><td>审批界面展示范围；人作出决定</td><td>说明范围及期限的决定</td><td>展示对象与实际操作不一致</td></tr><tr><td>保存决定</td><td>授权存储层写入所需的范围依据</td><td>可核对的批准记录</td><td>记录缺失或损坏</td></tr><tr><td>再次查找</td><td>授权层接到请求乙、目标乙</td><td>命中理由或重新询问</td><td>变化超出已同意的等价范围</td></tr><tr><td>暂停后恢复</td><td>恢复层取回等待请求与批准</td><td>当前请求的继续或拒绝决定</td><td>请求、策略或前置状态已变化</td></tr><tr><td>最终执行</td><td>工具边界重新核验当前权限</td><td>实际副作用与结果证据</td><td>权限撤销、重复消费或隔离措施不满足约定</td></tr></tbody></table><p>检查时一次只改一个维度：请求编号、目标、参数、函数体、策略版本、前置状态、时间或恢复上下文。先记录设计上应复用还是应重问，再穿过真实入口观察；不能把“符合现有查询”当成“符合用户授权”的同义词。还应分别检查批准是否一次性消费、网络重试是否重放旧决定，以及进程、容器或操作系统权限是否提供兜底。本文没有核验这些能力，不能从应用层的一次允许推断它们存在。</p><h2 id="证据与尚未完成的验证" tabindex="-1">证据与尚未完成的验证 <a class="header-anchor" href="#证据与尚未完成的验证" aria-label="Permalink to &quot;证据与尚未完成的验证&quot;">​</a></h2><p>本文区分三类依据：公开源码支持固定版本的实现事实；维护者测试只表示作者写下的预期；内部实验表示我们在限定环境执行了查询或函数，既不是独立第三方复现，也不是整个系统的安全验证。比较与建议则是从这些材料作出的研究解释。</p><p>源码固定于 AG2 的 <code>10809bf298ff7c5c5a5c830651070c6f6634f90f</code> 与 SIDJUA 的 <code>747b5bb125c8cc94e7cb99a581dc63bedb2c9bb2</code>，同日完成本地读取核验；不声称之后版本仍然相同。公开来源分别由框架维护者与格茨·科尔贝格提供：审批中间件、工具身份与上下文为实现源码，审批测试为作者测试，SIDJUA 两份文件为审批查询及管线源码。各处链接指向固定版本；不借来源的发布或引用状态增加结论强度。</p><p>内部 SQL（结构化查询语言）实验使用数据库版本 3.53.3 与执行环境版本 24.19.0；身份实验使用解释器版本 3.12.9。供读者核对的<a href="/joinwell52/assets/evidence/2026-11-14-sig-20261114-003/evidence-index.json">证据索引</a>保留原始结果、来源校验码、环境与合成对照，并声明脱敏处理。该附件是候选稿拟携带的公开证据包，不表示文章已经发布。</p><p>没有执行完整审批中间件、真实人工交互、会话恢复、传输合并、匹配器、条件解析器、决策写入器、恢复令牌校验器或外部工具；没有测量实际副作用，也没有证明攻击者能控制相关身份。对传输变量的过滤函数做过源码阅读，不等于所有入口均已审计。全系统漏洞、撤销保证、并发一次性消费与操作系统隔离都超出已有证据。</p><p>下一步应先向维护者核对预期范围，再以可信请求构造和真实恢复入口验证：换请求与换目标是否应当重新批准、代码更新后旧决定是否继续有效、拒绝与过期如何传播、重复调用是否产生多次效果。<strong>在这些证据补齐前，能确定的是两种复用键的边界，而不是系统整体是否安全。</strong></p>`,34))])}const f=d(l,[["render",p]]);export{u as __pageData,f as default};
